ST.xhtml:p:
Filter_1(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(FilterTime))),bDualStation1ExternalSignalLogic,g_biDualStation1TriggerStartSignal,bFilterDualStation1ExternalSignal);
bFilterDualStation1ExternalSignalTriggered := FUN_SingalLogic(bFilterDualStation1ExternalSignal,bDualStation1ExternalSignalLogic);

Filter_2(LREAL_TO_TIME(FUN_MSTOS(LREAL_TO_DINT(FilterTime))),bDualStation2ExternalSignalLogic,g_biDualStation2TriggerStartSignal,bFilterDualStation2ExternalSignal);
bFilterDualStation2ExternalSignalTriggered := FUN_SingalLogic(bFilterDualStation2ExternalSignal,bDualStation2ExternalSignalLogic);

DualStation1ExterSignal(CLK := g_biDualStation1TriggerStartSignal);
DualStation2ExterSignal(CLK := g_biDualStation2TriggerStartSignal);



IF DualStation1ExterSignal.Q  THEN
  IF NOT g_bDualStation1IsCuttingStatus THEN
	g_bDualStation1ExternalSignalTriggered := TRUE;
  END_IF;
END_IF;
IF DualStation2ExterSignal.Q  THEN
   IF NOT g_bDualStation2IsCuttingStatus THEN
		g_bDualStation2ExternalSignalTriggered := TRUE;
	END_IF;
END_IF;
